      END_STATE();
    case 14:
      ACCEPT_TOKEN(sym_data);
      END_STATE();
    case 15:
      if (lookahead == 'a') ADVANCE(18);
      END_STATE();
    case 16:
      if (lookahead == 't') ADVANCE(19);
      END_STATE();
    case 17:
      ACCEPT_TOKEN(sym_with);
      END_STATE();
    case 18:
      if (lookahead == 'n') ADVANCE(20);
      END_STATE();
    case 19:
      ACCEPT_TOKEN(sym_trait);
      END_STATE();
    case 20:
      if (lookahead == 'c') ADVANCE(21);
      END_STATE();
    case 21:
      if (lookahead == 'e') ADVANCE(22);
      END_STATE();
    case 22:
      ACCEPT_TOKEN(sym_instance);
      END_STATE();
    default:
      return false;
